import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.CDpkVv68.js";const g=JSON.parse('{"title":"Combat Variable Registry","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/combat/variable-registry.md","filePath":"en/game-design/combat/variable-registry.md"}'),n={name:"en/game-design/combat/variable-registry.md"};function i(o,t,s,c,l,m){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="combat-variable-registry" tabindex="-1">Combat Variable Registry <a class="header-anchor" href="#combat-variable-registry" aria-label="Permalink to &quot;Combat Variable Registry&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> Numeric examples are prototype hypotheses, not final balance. <strong>Implementation/availability:</strong> not established for these mechanics. <strong>Verification:</strong> documentation review, no playable prototype. <strong>Reviewed:</strong> 2026-10-09, Batch 05.</p><p><a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/combat/overview.html">Combat foundations</a> · <a href="/Syrolands-Public/en/game-design/combat/variable-registry.html">Combat Variable Registry</a></p><h2 id="scope-and-reading-rules" tabindex="-1">Scope and reading rules <a class="header-anchor" href="#scope-and-reading-rules" aria-label="Permalink to &quot;Scope and reading rules&quot;">​</a></h2><p>This registry normalizes <strong>40 concepts</strong> already present in combat, item, character and magic proposals. It is not a formula sheet, 40 new serialized fields or an implementation catalogue. Status describes the scoped design below; existing Accepted foundations and experimental policies keep their original limits. Numerical prototype examples elsewhere are not defaults.</p><p>Tables share stable IDs to keep definitions separate from disclosure/tuning on small screens. Owners retain mechanics; the registry reconciles names. “Needs prototype/tuning” means future work, not permission to change an accepted current value.</p><h2 id="definitions-and-dependencies" tabindex="-1">Definitions and dependencies <a class="header-anchor" href="#definitions-and-dependencies" aria-label="Permalink to &quot;Definitions and dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID / Variable</th><th>Definition</th><th>Applies to</th><th>Inputs/dependencies</th><th>Gameplay effect</th><th>Status / canonical owner</th></tr></thead><tbody><tr><td>C01 — Accuracy</td><td>Chance/quality of valid hit or placement</td><td>Attacks/spells</td><td>Skill, range, movement, aim</td><td>Hit outcome</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/legacy-and-modern.html">owner</a></td></tr><tr><td>C02 — Stamina / cost</td><td>Available physical resource versus per-action expenditure</td><td>Martial actions</td><td>Action, handling, fatigue, fluency</td><td>Sustainable action budget</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C03 — Wind-up</td><td>Preparation before active execution</td><td>Actions</td><td>Action class, fluency</td><td>Commitment and counter opportunity</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C04 — Active window</td><td>When authoritative contact may resolve</td><td>Actions</td><td>Action phase and geometry</td><td>Opportunity interval</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C05 — Recovery</td><td>Post-action restrictions before another action</td><td>Actions</td><td>Weapon, costs, handling</td><td>Limits chaining</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C06 — Handling modifiers</td><td>Control, cost and recovery contributions</td><td>Weapons/actions</td><td>Quality, stats, fatigue, fluency</td><td>Ease of execution</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">owner</a></td></tr><tr><td>C07 — Character stats</td><td>DEX/STR/INT capabilities, not blanket damage bonuses</td><td>Characters</td><td>Build, equipment and preparation</td><td>Bounded control/handling/cognitive support</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/characters/stats.html">owner</a></td></tr><tr><td>C08 — Consistency</td><td>Repeatability/variance, distinct from hit chance</td><td>Actions/spells</td><td>Skill, quality, Familiarity</td><td>Stable execution</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C09 — Telegraph strength/readability</td><td>Information conveyed before commitment resolves</td><td>Actions</td><td>Action, fluency, Tactics</td><td>Opponent reading and counterplay</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C10 — Reach</td><td>Maximum physically credible action distance</td><td>All weapons</td><td>Weapon/action geometry</td><td>Spatial eligibility</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/reach-and-spacing.html">owner</a></td></tr><tr><td>C11 — Minimum/effective range</td><td>Too-close limit and sweet-spot bands</td><td>Weapons/actions</td><td>Weapon handling, action</td><td>Legal/effective spacing</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/reach-and-spacing.html">owner</a></td></tr><tr><td>C12 — Timing/cadence</td><td>Attack initiation opportunities, distinct from phases</td><td>Legacy/Modern</td><td>Mode, weapon, recovery, bounded DEX</td><td>Automatic schedule or controlled initiation</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/legacy-and-modern.html">owner</a></td></tr><tr><td>C13 — Flow</td><td>Stable valid-input rhythm state</td><td>Modern</td><td>Spacing of valid actions</td><td>Explicit sustainable-rhythm trade-offs</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/flow.html">owner</a></td></tr><tr><td>C14 — Fatigue</td><td>Sustained exertion limitation</td><td>Combat</td><td>Exertion, stamina, recovery</td><td>Pressure on repeat performance</td><td>Unresolved; <a href="/Syrolands-Public/en/game-design/combat/stamina-and-reactive-combat.html">owner</a></td></tr><tr><td>C15 — Movement state</td><td>Motion/posture across action phases</td><td>Actors</td><td>Input, action restrictions</td><td>Aim, spacing and interruption</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C16 — Interruptibility</td><td>Which pressure can disrupt which phase</td><td>Actions/casts</td><td>Phase, damage, counters, Concentration</td><td>Cancellation or disruption</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C17 — Spatial footprint</td><td>Shape/area of possible contact</td><td>Actions/effects</td><td>Action geometry and pattern</td><td>Affected space, not guaranteed hits</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/reach-and-spacing.html">owner</a></td></tr><tr><td>C18 — Damage/trauma profile</td><td>Global injury versus local structural effect</td><td>Weapons/spells</td><td>Type, impact, mitigation</td><td>Separate global and local outcomes</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/weapons-and-damage.html">owner</a></td></tr><tr><td>C19 — Armor interaction / penetration / transmission</td><td>How protection blocks or transmits effects</td><td>Impact</td><td>Armor/material, weapon and action</td><td>Post-protection outcome</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/armor-and-mitigation.html">owner</a></td></tr><tr><td>C20 — Familiarity</td><td>Learned, Practiced, Mastered fluency</td><td>SAs/spell patterns</td><td>Qualifying use and active days</td><td>Execution, not permanent acquisition</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/characters/familiarity.html">owner</a></td></tr><tr><td>C21 — Weapon skill</td><td>General martial execution capability</td><td>Weapons/actions</td><td>Character progression</td><td>Capability envelope</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html">owner</a></td></tr><tr><td>C22 — Tactics / information skills</td><td>Permitted reading of actions and state</td><td>Combat information</td><td>Skill, cues, target knowledge</td><td>Information without prescribed response</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C23 — Action complexity</td><td>Preparation/execution burden</td><td>SAs/variants</td><td>Technique/modifiers</td><td>Preparation and cognitive trade-offs</td><td>Unresolved; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C24 — Counter relationship</td><td>Compatible responses and matchup constraints</td><td>Actions</td><td>Timing, direction, action family</td><td>Reduction, counter or failed response</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C25 — Global Hits</td><td>Overall health separate from local integrity</td><td>Actors</td><td>Damage and healing</td><td>Survival</td><td>Accepted; <a href="/Syrolands-Public/en/game-design/combat/damage.html">owner</a></td></tr><tr><td>C26 — Body-region integrity</td><td>Independent local structural condition</td><td>Anatomy regions</td><td>Region profile and Local Trauma</td><td>Local condition/disability</td><td>Accepted; <a href="/Syrolands-Public/en/game-design/combat/body-regions.html">owner</a></td></tr><tr><td>C27 — Local Trauma policy</td><td>Current bounded experimental local damage conversion</td><td>Existing experiment</td><td>Post-mitigation residual, lifecycle, actual HP loss</td><td>Local integrity loss; not universal magic formula</td><td>Experimental; <a href="/Syrolands-Public/en/game-design/combat/damage.html">owner</a></td></tr><tr><td>C28 — Impact region / targeting intent</td><td>Requested region differs from resolved location</td><td>Localized actions</td><td>Anatomy, validity and impact profile</td><td>Determines affected region</td><td>Accepted; <a href="/Syrolands-Public/en/game-design/combat/targeting.html">owner</a></td></tr><tr><td>C29 — Armor condition / coverage</td><td>Item wear and protected contact regions</td><td>Equipment</td><td>Material, item, condition</td><td>Protection availability</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/armor-and-mitigation.html">owner</a></td></tr><tr><td>C30 — Item structural integrity</td><td>Resistance to breakage, not body integrity</td><td>Items</td><td>Material and quality</td><td>Equipment durability</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">owner</a></td></tr><tr><td>C31 — Functional retention</td><td>Maintaining intended performance with use</td><td>Items</td><td>Wear, treatment, material</td><td>Degradation of function</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">owner</a></td></tr><tr><td>C32 — Offensive efficiency</td><td>Converting correct execution into effect</td><td>Weapons</td><td>Quality and family</td><td>Effectiveness without flat DPS ladder</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">owner</a></td></tr><tr><td>C33 — Mana / resource cost</td><td>Magical resource availability and expenditure</td><td>Spells</td><td>Pattern, INT relationship, modifiers</td><td>Cast affordability</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/magic.html">owner</a></td></tr><tr><td>C34 — Concentration</td><td>Stability under pressure, not automatically a skill</td><td>Magic</td><td>Damage, trauma, movement, Meditation</td><td>Cast sustain/interruption</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/magic.html">owner</a></td></tr><tr><td>C35 — Spell Difficulty / attempt floor</td><td>Eligibility differs from execution challenge</td><td>Magic</td><td>Pattern, Magery, modifiers, Mastery</td><td>Attempt access and fizzle</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/magic.html">owner</a></td></tr><tr><td>C36 — Active Memory / reference delay</td><td>Prepared spell complexity and extra lookup</td><td>Magic</td><td>Knowledge, INT, Familiarity, Meditation</td><td>Readiness before normal cast</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/magic/memory-and-familiarity.html">owner</a></td></tr><tr><td>C37 — Prepared Combat Repertoire</td><td>Ready SA selection, not total knowledge</td><td>Martial actions</td><td>Learned actions, slot proposal</td><td>Prepared options</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/combat/actions.html">owner</a></td></tr><tr><td>C38 — Orientation / LOS / target validity</td><td>Eligibility of the intended action against space and target</td><td>Combat</td><td>Position, obstacles, target state</td><td>Valid attempt/contact</td><td>Accepted server validation; Proposed action-specific orientation; <a href="/Syrolands-Public/en/game-design/combat/overview.html">owner</a></td></tr><tr><td>C39 — Familiarity maintenance</td><td>Activity-based fluency retention</td><td>SAs/spell patterns</td><td>Qualifying uses, active days, facilities</td><td>Maintenance/decay without lost knowledge</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/characters/familiarity.html">owner</a></td></tr><tr><td>C40 — Reagents / scroll material cost</td><td>Physical magical material expenditure</td><td>Magic</td><td>Pattern, variant, scroll, failure policy</td><td>Material risk and temporary access</td><td>Proposed; <a href="/Syrolands-Public/en/game-design/magic/spellbooks-scrolls-and-reagents.html">owner</a></td></tr></tbody></table><h2 id="disclosure-representation-and-validation" tabindex="-1">Disclosure, representation and validation <a class="header-anchor" href="#disclosure-representation-and-validation" aria-label="Permalink to &quot;Disclosure, representation and validation&quot;">​</a></h2><p>Visibility below is a design direction, not a UI capability claim. Exact values need not be exposed merely because the server uses numbers.</p><table tabindex="0"><thead><tr><th>ID / Variable</th><th>Player-visible?</th><th>Suggested representation</th><th>Needs prototype?</th><th>Needs numeric tuning?</th></tr></thead><tbody><tr><td>C01 — Accuracy</td><td>Outcome/cues; exact values unresolved</td><td>numeric/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C02 — Stamina / cost</td><td>Resource/selection feedback; exact UI unresolved</td><td>numeric/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C03 — Wind-up</td><td>Outcome/cues; exact values unresolved</td><td>duration</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C04 — Active window</td><td>Outcome/cues; exact values unresolved</td><td>duration</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C05 — Recovery</td><td>Outcome/cues; exact values unresolved</td><td>duration/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C06 — Handling modifiers</td><td>Outcome/cues; exact values unresolved</td><td>tier/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C07 — Character stats</td><td>Resource/selection feedback; exact UI unresolved</td><td>numeric; formulas open</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C08 — Consistency</td><td>Outcome/cues; exact values unresolved</td><td>tier/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C09 — Telegraph strength/readability</td><td>Outcome/cues; exact values unresolved</td><td>qualitative cues</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C10 — Reach</td><td>Outcome/cues; exact values unresolved</td><td>distance</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C11 — Minimum/effective range</td><td>Outcome/cues; exact values unresolved</td><td>distance/bands</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C12 — Timing/cadence</td><td>Outcome/cues; exact values unresolved</td><td>interval/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C13 — Flow</td><td>Outcome/cues; exact values unresolved</td><td>derived; UI unresolved</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C14 — Fatigue</td><td>Outcome/cues; exact values unresolved</td><td>derived or separate TBD</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C15 — Movement state</td><td>Outcome/cues; exact values unresolved</td><td>state</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C16 — Interruptibility</td><td>Outcome/cues; exact values unresolved</td><td>rules/tier</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C17 — Spatial footprint</td><td>Outcome/cues; exact values unresolved</td><td>shape/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C18 — Damage/trauma profile</td><td>Outcome/cues; exact values unresolved</td><td>profile</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C19 — Armor interaction / penetration / transmission</td><td>Outcome/cues; exact values unresolved</td><td>profile/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C20 — Familiarity</td><td>Outcome/cues; exact values unresolved</td><td>tier</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C21 — Weapon skill</td><td>Resource/selection feedback; exact UI unresolved</td><td>numeric</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C22 — Tactics / information skills</td><td>Outcome/cues; exact values unresolved</td><td>qualitative disclosure</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C23 — Action complexity</td><td>Outcome/cues; exact values unresolved</td><td>tier/budget TBD</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C24 — Counter relationship</td><td>Outcome/cues; exact values unresolved</td><td>relationship</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C25 — Global Hits</td><td>Resource/selection feedback; exact UI unresolved</td><td>numeric</td><td>Yes, for proposed integration</td><td>Existing scope preserved; future changes separately reviewed</td></tr><tr><td>C26 — Body-region integrity</td><td>Outcome/cues; exact values unresolved</td><td>numeric/qualitative display</td><td>Yes, for proposed integration</td><td>Existing scope preserved; future changes separately reviewed</td></tr><tr><td>C27 — Local Trauma policy</td><td>Outcome/cues; exact values unresolved</td><td>derived</td><td>Yes, for proposed integration</td><td>Existing scope preserved; future changes separately reviewed</td></tr><tr><td>C28 — Impact region / targeting intent</td><td>Outcome/cues; exact values unresolved</td><td>state/qualitative</td><td>Yes, for proposed integration</td><td>Existing scope preserved; future changes separately reviewed</td></tr><tr><td>C29 — Armor condition / coverage</td><td>Outcome/cues; exact values unresolved</td><td>state/tier</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C30 — Item structural integrity</td><td>Outcome/cues; exact values unresolved</td><td>tier/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C31 — Functional retention</td><td>Outcome/cues; exact values unresolved</td><td>tier/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C32 — Offensive efficiency</td><td>Outcome/cues; exact values unresolved</td><td>tier/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C33 — Mana / resource cost</td><td>Resource/selection feedback; exact UI unresolved</td><td>numeric; redesign unresolved</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C34 — Concentration</td><td>Outcome/cues; exact values unresolved</td><td>state/meter TBD</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C35 — Spell Difficulty / attempt floor</td><td>Outcome/cues; exact values unresolved</td><td>threshold/derived</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C36 — Active Memory / reference delay</td><td>Outcome/cues; exact values unresolved</td><td>budget/duration TBD</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C37 — Prepared Combat Repertoire</td><td>Resource/selection feedback; exact UI unresolved</td><td>slots/state</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C38 — Orientation / LOS / target validity</td><td>Outcome/cues; exact values unresolved</td><td>server state; feedback</td><td>Yes, for proposed integration</td><td>Existing scope preserved; future changes separately reviewed</td></tr><tr><td>C39 — Familiarity maintenance</td><td>Outcome/cues; exact values unresolved</td><td>rolling count/state</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr><tr><td>C40 — Reagents / scroll material cost</td><td>Resource/selection feedback; exact UI unresolved</td><td>inventory/cost</td><td>Yes, for proposed integration</td><td>See Batch 06 triage; broader tuning remains open</td></tr></tbody></table><h2 id="duplicate-and-conflict-reconciliation" tabindex="-1">Duplicate and conflict reconciliation <a class="header-anchor" href="#duplicate-and-conflict-reconciliation" aria-label="Permalink to &quot;Duplicate and conflict reconciliation&quot;">​</a></h2><ul><li>Accuracy is hit/placement chance; Consistency is repeatability. The earlier item dimension “Precision / Consistency” can support both, but is not a second unconditional hit bonus.</li><li>Handling feeds cost/recovery/control; do not double-count it as a separate flat damage bonus. Offensive Efficiency is a different item-quality concept.</li><li>Cadence governs initiation; wind-up, active window and recovery govern action phases. Animation duration is presentation, not a second authority clock. Reference delay is extra spell lookup, not all casting time.</li><li>Stamina is a resource; cost is an expenditure; fatigue&#39;s independent-versus-derived representation remains unresolved. Flow tracks rhythm; Familiarity tracks practiced fluency over active days.</li><li>Body integrity, item structural integrity and armor condition are different domains. Global damage, Local Trauma and armor transmission must not collapse into one damage variable.</li><li>Maximum reach, minimum range, effective/sweet-spot range and footprint describe different spatial constraints. Target intent, actual region and target validity are distinct.</li><li>Prepared Combat Repertoire and magical Active Memory are related preparation concepts with different unresolved budgets. Wider magic Mastery is not the shared Familiarity tier named Mastered.</li><li>Tactics&#39; information cues do not replace existing Anatomy/region knowledge or reveal an automatic counter solution. Exact information-skill allocation remains open.</li><li>Existing Local Trauma arithmetic remains an experimental scoped policy; the registry assigns no replacement values and does not transfer it to every spell, area effect or creature.</li></ul><h2 id="prototype-handoff" tabindex="-1">Batch 05 handoff (historical) <a class="header-anchor" href="#prototype-handoff" aria-label="Permalink to &quot;Batch 05 handoff (historical)&quot;">​</a></h2><p>Choose a small set of actions, fill the <a href="/Syrolands-Public/en/game-design/combat/actions.html#canonical-action-schema">action schema</a>, test both modes, measure resource/cadence trade-offs and spatial readability, then propose numbers with provenance. Include latency/accessibility, macro resistance and failure reasons. That Batch 05 handoff assigned no new values. Batch 06 now defines a separate Experimental numeric profile below; it still authorizes no gameplay code.</p><h2 id="batch-06-implementation-triage" tabindex="-1">Batch 06 implementation triage <a class="header-anchor" href="#batch-06-implementation-triage" aria-label="Permalink to &quot;Batch 06 implementation triage&quot;">​</a></h2><p><strong>Experimental test scope, not implementation authorization.</strong> A = Numeric now; B = Qualitative/tier for now; C = Derived; D = Defer. Defer means no new model in this three-weapon slice, not removal of an Accepted foundation. Fixed fixture controls are not new progression variables. Derived values may need transient server bookkeeping; they should not become independent persisted/tunable stats.</p><p>Counts: <strong>A: 13</strong>, <strong>B: 10</strong>, <strong>C: 7</strong>, <strong>D: 10</strong>. Numeric cells below refer only to the <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html">single Experimental profile</a>; existing stronger-status policies remain unchanged. Canonical owners below retain broader semantics.</p><table tabindex="0"><thead><tr><th>ID / variable</th><th>Class</th><th>Reason</th><th>Prototype representation</th><th>Owner</th><th>Later tuning dependency</th></tr></thead><tbody><tr><td>C01 — Accuracy</td><td>A</td><td>Comparable hit fixture</td><td>75% fixture + pp; clamp 5–95%</td><td><a href="/Syrolands-Public/en/game-design/combat/legacy-and-modern.html">Owner</a></td><td>Skill/armor integration</td></tr><tr><td>C02 — Stamina / cost</td><td>A</td><td>Test resource pressure</td><td>100 pool; costs and 6/s regeneration</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Sustain, chase and defense</td></tr><tr><td>C03 — Wind-up</td><td>A</td><td>Readable commitment</td><td>Action W in ms</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Animation readability</td></tr><tr><td>C04 — Active window</td><td>A</td><td>Define contact opportunity</td><td>Action A in ms; one contact rule</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Latency and contact resolver</td></tr><tr><td>C05 — Recovery</td><td>A</td><td>Gate repeat attacks</td><td>Action R in ms; bounded factors</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Tempo and whiff punish</td></tr><tr><td>C06 — Handling modifiers</td><td>B</td><td>Avoid quality formula now</td><td>Neutral; low/standard/high labels; isolated ±3% cadence sensitivity</td><td><a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">Owner</a></td><td>Craft-quality mapping</td></tr><tr><td>C07 — Character stats</td><td>A</td><td>Bound DEX effect explicitly</td><td>DEX 50 baseline; 0/100 trials, ±5% Legacy contribution; STR/INT neutral</td><td><a href="/Syrolands-Public/en/game-design/characters/stats.html">Owner</a></td><td>Build diversity</td></tr><tr><td>C08 — Consistency</td><td>B</td><td>No second damage RNG</td><td>Reduced / standard / refined feedback only</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Variance model if useful</td></tr><tr><td>C09 — Telegraph strength/readability</td><td>B</td><td>Readable cue tiers</td><td>Medium / strong / very strong, no hidden cues</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Assets and accessibility</td></tr><tr><td>C10 — Reach</td><td>A</td><td>Spacing is a core trial</td><td>1/2/3-tile action maxima</td><td><a href="/Syrolands-Public/en/game-design/combat/reach-and-spacing.html">Owner</a></td><td>Visible reach feasibility</td></tr><tr><td>C11 — Minimum/effective range</td><td>A</td><td>Distinguish legal and ideal</td><td>Spear 1-tile −10 pp, ×0.85; ideal 2, Lunge 2–3</td><td><a href="/Syrolands-Public/en/game-design/combat/reach-and-spacing.html">Owner</a></td><td>Close-range fairness</td></tr><tr><td>C12 — Timing/cadence</td><td>C</td><td>Calculate from phases</td><td>T=W+A+1.5R; Legacy bounded multiplier</td><td><a href="/Syrolands-Public/en/game-design/combat/legacy-and-modern.html">Owner</a></td><td>Phase/resource trials</td></tr><tr><td>C13 — Flow</td><td>C</td><td>Transient rhythm, not saved stat</td><td>Off Rhythm / Stable / Flow from accepted intervals</td><td><a href="/Syrolands-Public/en/game-design/combat/flow.html">Owner</a></td><td>Latency and forgiving windows</td></tr><tr><td>C14 — Fatigue</td><td>C</td><td>Avoid independent meter</td><td>1−stamina/100 contribution only</td><td><a href="/Syrolands-Public/en/game-design/combat/stamina-and-reactive-combat.html">Owner</a></td><td>Long-fight observations</td></tr><tr><td>C15 — Movement state</td><td>B</td><td>Keep movement discrete</td><td>Walk / planted; running cancels wind-up</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Movement feel</td></tr><tr><td>C16 — Interruptibility</td><td>B</td><td>Use state rules</td><td>Wind-up cancel; no damage-only interrupt</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Counter and lifecycle tests</td></tr><tr><td>C17 — Spatial footprint</td><td>B</td><td>Use fixed templates</td><td>Ray / front sector / capped arc</td><td><a href="/Syrolands-Public/en/game-design/combat/reach-and-spacing.html">Owner</a></td><td>Geometry, target filtering</td></tr><tr><td>C18 — Damage/trauma profile</td><td>A</td><td>Compare profiles without HP balance</td><td>Relative D0 multipliers; trauma emphasis qualitative</td><td><a href="/Syrolands-Public/en/game-design/combat/weapons-and-damage.html">Owner</a></td><td>Accepted pipeline integration</td></tr><tr><td>C19 — Armor interaction / penetration / transmission</td><td>B</td><td>No armor redesign</td><td>Piercing/blunt identity labels; current mitigation retained</td><td><a href="/Syrolands-Public/en/game-design/combat/armor-and-mitigation.html">Owner</a></td><td>Materials and shield composition</td></tr><tr><td>C20 — Familiarity</td><td>A</td><td>Small execution deltas</td><td>Three martial tier factor rows; no spell numbers</td><td><a href="/Syrolands-Public/en/game-design/characters/familiarity.html">Owner</a></td><td>Tier accessibility and skill separation</td></tr><tr><td>C21 — Weapon skill</td><td>B</td><td>Hold confounder constant</td><td>Equal-skill fixture at 50; no new gain or hit formula</td><td><a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html">Owner</a></td><td>Skill progression later</td></tr><tr><td>C22 — Tactics / information skills</td><td>B</td><td>No threshold guessing</td><td>Generic/family cue tiers; no numeric Tactics gate</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Information readability</td></tr><tr><td>C23 — Action complexity</td><td>D</td><td>Not needed for 5-slot trial</td><td>No complexity score</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Expanded catalogue</td></tr><tr><td>C24 — Counter relationship</td><td>A</td><td>Test defense and baiting</td><td>Brace/Riposte reductions, one counter; Guard Break halves reduction</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Mitigation composition</td></tr><tr><td>C25 — Global Hits</td><td>D</td><td>Preserve existing health system</td><td>Existing fixture Hits unchanged; no new target</td><td><a href="/Syrolands-Public/en/game-design/combat/damage.html">Owner</a></td><td>Later HP/TTK calibration</td></tr><tr><td>C26 — Body-region integrity</td><td>D</td><td>Preserve existing regional state</td><td>Existing integrity unchanged; no new total</td><td><a href="/Syrolands-Public/en/game-design/combat/body-regions.html">Owner</a></td><td>Localized runtime evidence</td></tr><tr><td>C27 — Local Trauma policy</td><td>C</td><td>Existing experimental formula owns it</td><td>Derive from accepted residual/lifecycle policy, no new factor</td><td><a href="/Syrolands-Public/en/game-design/combat/damage.html">Owner</a></td><td>Damage pipeline reconciliation</td></tr><tr><td>C28 — Impact region / targeting intent</td><td>C</td><td>Outcome from validated contact</td><td>Intent differs from resolved impact; no new tunable</td><td><a href="/Syrolands-Public/en/game-design/combat/targeting.html">Owner</a></td><td>Targeting and anatomy</td></tr><tr><td>C29 — Armor condition / coverage</td><td>B</td><td>Control armor fixture</td><td>Fixed intact equipment; no new wear rule</td><td><a href="/Syrolands-Public/en/game-design/combat/armor-and-mitigation.html">Owner</a></td><td>Armor/material trial</td></tr><tr><td>C30 — Item structural integrity</td><td>D</td><td>No item-break loop required</td><td>Keep existing item behavior</td><td><a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">Owner</a></td><td>Crafting and durability</td></tr><tr><td>C31 — Functional retention</td><td>D</td><td>Avoid a second wear system</td><td>No new retention stat</td><td><a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">Owner</a></td><td>Long-term degradation</td></tr><tr><td>C32 — Offensive efficiency</td><td>C</td><td>Do not double-count damage</td><td>Observe effectiveness from profile, accuracy and costs</td><td><a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">Owner</a></td><td>Item-quality trial</td></tr><tr><td>C33 — Mana / resource cost</td><td>D</td><td>No spell kit in this batch</td><td>Existing magic unchanged</td><td><a href="/Syrolands-Public/en/game-design/magic.html">Owner</a></td><td>Magic slice</td></tr><tr><td>C34 — Concentration</td><td>D</td><td>No casting in this slice</td><td>No concentration meter</td><td><a href="/Syrolands-Public/en/game-design/magic.html">Owner</a></td><td>Magic interruption design</td></tr><tr><td>C35 — Spell Difficulty / attempt floor</td><td>D</td><td>No spell difficulty assignment</td><td>No new thresholds</td><td><a href="/Syrolands-Public/en/game-design/magic.html">Owner</a></td><td>Core Pattern testing</td></tr><tr><td>C36 — Active Memory / reference delay</td><td>D</td><td>Not martial slots</td><td>No memory capacity or lookup time</td><td><a href="/Syrolands-Public/en/game-design/magic/memory-and-familiarity.html">Owner</a></td><td>Magic preparation</td></tr><tr><td>C37 — Prepared Combat Repertoire</td><td>A</td><td>Ready options need a bound</td><td>5 slots; 10 s safe swap gate</td><td><a href="/Syrolands-Public/en/game-design/combat/actions.html">Owner</a></td><td>Loadout UX</td></tr><tr><td>C38 — Orientation / LOS / target validity</td><td>C</td><td>Validation from world state</td><td>Existing LOS/validity plus proposed fixed facing footprints</td><td><a href="/Syrolands-Public/en/game-design/combat/overview.html">Owner</a></td><td>Geometry and server contracts</td></tr><tr><td>C39 — Familiarity maintenance</td><td>A</td><td>Explicit retention trial</td><td>7 active days; 20/5 Mastered, 9/3 Practiced; 10 min active threshold</td><td><a href="/Syrolands-Public/en/game-design/characters/familiarity.html">Owner</a></td><td>Abuse controls and tier gains</td></tr><tr><td>C40 — Reagents / scroll material cost</td><td>D</td><td>No reagent balance required</td><td>Existing resources unchanged</td><td><a href="/Syrolands-Public/en/game-design/magic/spellbooks-scrolls-and-reagents.html">Owner</a></td><td>Magic/Inscription slice</td></tr></tbody></table>',19)])])}const p=e(n,[["render",i]]);export{g as __pageData,p as default};
